import{_ as o,a as t,b as r}from"./chunks/exprx.CcoobiI_.js";import{_ as l}from"./chunks/sh5._o0Xe7oD.js";import{_ as n,c as e,o as i,ae as s}from"./chunks/framework.CDjunVez.js";const q=JSON.parse('{"title":"コンダクターワンド (Conductor Wand)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/conductor_wand.md","filePath":"ja/manual/conductor_wand.md"}'),d={name:"ja/manual/conductor_wand.md"};function c(u,a,h,_,g,m){return i(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="コンダクターワンド-conductor-wand" tabindex="-1">コンダクターワンド (Conductor Wand) <a class="header-anchor" href="#コンダクターワンド-conductor-wand" aria-label="Permalink to &quot;コンダクターワンド (Conductor Wand)&quot;">​</a></h1><p><strong>コンダクターワンド</strong> は、大規模な Note Block プロジェクト向けに設計されたツールです。WorldEdit のように領域を選択し、その範囲内にあるすべての Extended Note Block の属性を一括編集できます。</p><h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><h3 id="_1-領域選択" tabindex="-1">1. 領域選択 <a class="header-anchor" href="#_1-領域選択" aria-label="Permalink to &quot;1. 領域選択&quot;">​</a></h3><ul><li><strong>ポイント1設定 (Pos1)</strong>: ワンドを持ってブロックを <strong>左クリック</strong> します。 <img src="'+o+'" alt="Pos1"></li><li><strong>ポイント2設定 (Pos2)</strong>: ワンドを持ってブロックを <strong>右クリック</strong> します。 <img src="'+t+'" alt="Pos2"></li><li>選択が完了すると、画面に選択範囲が表示されます。</li><li>Backspace キーを長押しすると、選択をキャンセルできます。</li></ul><h3 id="_2-編集インターフェースを開く" tabindex="-1">2. 編集インターフェースを開く <a class="header-anchor" href="#_2-編集インターフェースを開く" aria-label="Permalink to &quot;2. 編集インターフェースを開く&quot;">​</a></h3><ul><li>2つのポイントを選択した後、Enter キーを押すとコンダクターインターフェースが開きます。 <img src="'+l+'" alt="ConductorScreen"><img src="'+r+'" alt="ExprX"></li></ul><h2 id="一括編集機能" tabindex="-1">一括編集機能 <a class="header-anchor" href="#一括編集機能" aria-label="Permalink to &quot;一括編集機能&quot;">​</a></h2><p>インターフェースには、Extended Note Block の編集可能なすべてのパラメータが一覧表示されます。各パラメータの前には <strong>モード切替ボタン</strong> があります：</p><h3 id="編集モードの詳細" tabindex="-1">編集モードの詳細 <a class="header-anchor" href="#編集モードの詳細" aria-label="Permalink to &quot;編集モードの詳細&quot;">​</a></h3><ul><li><strong>維持 (K)</strong>: このパラメータを変更せず、ブロックの元の値を保持します。</li><li><strong>設定 (=)</strong>: 選択範囲内のすべてのブロックのこのパラメータを入力値に統一します。</li><li><strong>加算 (+)</strong>: ブロックの元の値に入力値を加算します（例：すべての音符を1オクターブ上げる場合は +12）。</li><li><strong>減算 (-)</strong>: 元の値から入力値を減算します。</li><li><strong>乗算 (x)</strong> / <strong>除算 (/)</strong>: パラメータを倍率でスケーリングします（ベロシティや遅延のパーセンテージ調整によく使用されます）。</li></ul><h3 id="サポートされているパラメータ" tabindex="-1">サポートされているパラメータ <a class="header-anchor" href="#サポートされているパラメータ" aria-label="Permalink to &quot;サポートされているパラメータ&quot;">​</a></h3><ul><li>音程 (Note)</li><li>力度 (Velocity)</li><li>持続音 (Sustain)</li><li>再生遅延 (Delay)</li><li>フェードイン/アウト</li><li>高度なモードのプロパティ</li></ul><h2 id="実用的なヒント" tabindex="-1">実用的なヒント <a class="header-anchor" href="#実用的なヒント" aria-label="Permalink to &quot;実用的なヒント&quot;">​</a></h2><ol><li><strong>素早い移調</strong>: 楽節を選択した後、「加算 (Add)」モードを使用して <code>12</code> または <code>-12</code> を入力するだけで、素早くオクターブの上げ下げができます。</li><li><strong>強弱のグラデーション</strong>: まず基礎となるベロシティを一括設定し、その後、高度なモードのエンベロープで細部を調整します。</li><li><strong>全体的なタイミング調整</strong>: 楽節が走っている（早まっている）場合、「加算 (Add)」モードを使用して遅延 (Delay) に一律の正の偏差を追加します。</li></ol>',15)])])}const P=n(d,[["render",c]]);export{q as __pageData,P as default};
